)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '合作完工', 'kp-eng-b-together', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "合作完工问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "多人同时参与工作。效率可以无脑相加，但时间绝对不能相加！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "给出了甲独做的时间、乙独做的时间，然后问“两人一起合作需要几天完成”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推论"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "合作效率 = 各自效率之和。", "marks": [{"type": "bold"}]}]}, {"type": "katexBlock", "attrs": {"content": "P_{合作} = P_A + P_B \\quad \\Rightarrow \\quad T_{合作} = \\frac{W}{P_A + P_B}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[赋总量 W (取单独完工时间的最小公倍数)] --> B[算出各自的效率 PA, PB]\nB --> C[求出合作总效率: P合 = PA + PB]\nC --> D[用总工程量 W 除以 P合]\nD --> E[得出合作总时间 T]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 打印一份文件，A打印机单打需 20 分钟，B打印机单打需 30 分钟。两台打印机同时开机合作，需要多少分钟打完？选项：A. 10  B. 12  C. 15  D. 25"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋总量：20 和 30 的公倍数取 60。设总任务 W = 60。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出效率：Pa = 60/20 = 3。Pb = 60/30 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算总效率：P合 = 3 + 2 = 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算合作时间：T合 = 60 ÷ 5 = 12 分钟。选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "时间直接相加减：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "初学者神逻辑：“A要20分，B要30分，合作不就是 (20+30)/2=25分 吗？”（甚至有人选D）。切记，多个人干活只会越来越快，合作时间必定小于其中任何一个人单独干的时间（必然小于20）。直接对时间做加减乘除是工程问题的大忌！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "对于两两合作，可以记一个速算公式（仅限两人）：T合 = (T1×T2) / (T1+T2)。比如上面的 20×30/(20+30) = 600/50 = 12。在简单题中可以直接秒杀。"}]}]}$$ AS jsonb), NULL, '合作完工的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "合作完工"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_b_together", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
